\version "2.27.2"
% automatically converted by musicxml2ly from 33c-Spanners-Slurs.xml
\pointAndClickOff

\header {
  texidoc = "A note can be the end of one slur and the start of a new slur.
    Also, in MusicXML, nested slurs are possible like in the second measure
    where one slur goes over all four notes, and another slur goes from the
    second to the third note.

    The third bar demonstrates a cross-voice slur starting at the first beat in
    the lower voice and ending on the third beat in the upper voice."
}
\layout {
  \context {
    \Staff
    printKeyCancellation = ##f
  }
  \context {
    \Score
    autoBeaming = ##f
  }
}
PartPOneVoiceOne = \relative g' {
  \clef "treble" \time 4/4 \key c \major \oneVoice g4 ^( c4 ) ^( a4 ) _( g4 ) | % 1
  g4 ^( c4 ^\=2( a4 \=2) g4 ) | % 2
  \voiceOne r2 a4 g4 \bar "|."
}

PartPOneVoiceTwo = \relative g' {
  \clef "treble" \time 4/4 \key c \major s1*2 | % 2
  g4 c4 r2 \bar "|."
}


% The score definition
\score {
  <<
    \new Staff = "P1" <<
      \context Staff <<
        \override Staff.BarLine.allow-span-bar = ##f
        \mergeDifferentlyDottedOn
        \mergeDifferentlyHeadedOn
        \context Voice = "PartPOneVoiceOne" {
          \voiceOne \PartPOneVoiceOne
        }
        \context Voice = "PartPOneVoiceTwo" {
          \voiceTwo \PartPOneVoiceTwo
        }
      >>
    >>
  >>
  \layout {}
